func (c *VerifiedPurchaseClient) MapCreateBulk(slice any, setFunc func(*VerifiedPurchaseCreate, int)) *VerifiedPurchaseCreateBulk {
	rv := reflect.ValueOf(slice)
	if rv.Kind() != reflect.Slice {
		return &VerifiedPurchaseCreateBulk{err: fmt.Errorf("calling to VerifiedPurchaseClient.MapCreateBulk with wrong type %T, need slice", slice)}
	}
	builders := make([]*VerifiedPurchaseCreate, rv.Len())
	for i := 0; i < rv.Len(); i++ {
		builders[i] = c.Create()
		setFunc(builders[i], i)
	}
	return &VerifiedPurchaseCreateBulk{config: c.config, builders: builders}
}

